<?php
require_once '../config.php'; require_admin(); $pageTitle='Manage bookings'; $message='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$status=$_POST['status']??'pending';if(in_array($status,['pending','approved','rejected','completed'],true)){$st=$pdo->prepare("UPDATE bookings SET status=? WHERE id=?");$st->execute([$status,(int)$_POST['id']]);$message='Booking status updated.';}}
$rows=$pdo->query("SELECT b.*,u.name AS customer,u.email,m.name AS motorcycle FROM bookings b JOIN users u ON u.id=b.user_id JOIN motorcycles m ON m.id=b.motorcycle_id ORDER BY b.created_at DESC")->fetchAll();require '../includes/header.php'; ?>
<section class="page-banner"><div class="container"><div class="eyebrow">ADMIN</div><h1>Manage bookings</h1></div></section><div class="container-fluid"><div class="row"><aside class="col-md-2 admin-sidebar"><a href="dashboard.php">Dashboard</a><a href="motorcycles.php">Motorcycles</a><a href="bookings.php">Bookings</a><a href="customers.php">Customers</a><a href="logout.php">Logout</a></aside><div class="col-md-10 p-4"><?php if($message): ?><div class="alert alert-success"><?= e($message) ?></div><?php endif; ?><div class="content-card"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Customer</th><th>Motorcycle</th><th>Dates</th><th>Total</th><th>Notes</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['customer']) ?><div class="small-muted"><?= e($r['email']) ?></div></td><td><?= e($r['motorcycle']) ?></td><td><?= e($r['start_date']) ?> to <?= e($r['end_date']) ?></td><td>₱<?= number_format((float)$r['total_amount'],2) ?></td><td><?= e($r['notes']) ?></td><td><form method="post" class="d-flex gap-1"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><select class="form-select form-select-sm" name="status"><?php foreach(['pending','approved','rejected','completed'] as $s): ?><option <?= $r['status']===$s?'selected':'' ?>><?= $s ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-dark">Save</button></form></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="text-secondary">No bookings found.</td></tr><?php endif; ?></tbody></table></div></div></div></div></div>
<?php require '../includes/footer.php'; ?>
